/**************************
 * Workflow DSL Builder
 *
 * Main factory function for creating durable workflows
 **************************/
import { INVALID_ARGUMENT } from "../../errors/index.js";
import { workflowRegistry } from "../registry.js";
import { validateWorkflowPathSegment } from "./validation.js";
/** Create a workflow definition. */
export function workflow(options) {
    if (!options.id)
        throw INVALID_ARGUMENT.create({ detail: "Workflow must have an 'id'" });
    validateWorkflowPathSegment(options.id, "Workflow ID");
    if (!options.steps) {
        throw INVALID_ARGUMENT.create({ detail: `Workflow "${options.id}" must have 'steps'` });
    }
    const definition = {
        id: options.id,
        description: options.description,
        version: options.version,
        inputSchema: options.inputSchema,
        outputSchema: options.outputSchema,
        output: options.output,
        integrationRequirements: options.integrationRequirements,
        retry: options.retry,
        timeout: options.timeout,
        introspect: options.introspect,
        steps: options.steps,
        onError: options.onError,
        onComplete: options.onComplete,
    };
    const wf = {
        definition,
        id: options.id,
        version: options.version,
    };
    // Auto-register for discovery in dev tools
    // Use type assertion since registry only stores metadata, not the full generic type
    workflowRegistry.register(wf);
    return wf;
}
/** Create a sequential workflow definition. */
export function sequence(...nodes) {
    return nodes.map((node, index) => {
        if (index === 0)
            return node;
        const previousId = nodes[index - 1].id;
        const existingDependencies = node.dependsOn ?? [];
        const dependencies = [];
        let includesPrevious = false;
        for (let dependencyIndex = 0; dependencyIndex < existingDependencies.length; dependencyIndex++) {
            const dependency = existingDependencies[dependencyIndex];
            dependencies[dependencyIndex] = dependency;
            if (dependency === previousId)
                includesPrevious = true;
        }
        if (!includesPrevious)
            dependencies[dependencies.length] = previousId;
        return {
            ...node,
            dependsOn: dependencies,
        };
    });
}
/** Create a directed workflow graph. */
export function dag(nodes) {
    const result = [];
    const seenIds = new Set();
    for (const [id, value] of Object.entries(nodes)) {
        const isWithDeps = "node" in value;
        const baseNode = isWithDeps ? value.node : value;
        const nodeId = baseNode.id || id;
        if (seenIds.has(nodeId)) {
            throw INVALID_ARGUMENT.create({ detail: `Duplicate node ID detected in dag: "${nodeId}"` });
        }
        seenIds.add(nodeId);
        result.push(isWithDeps
            ? { ...baseNode, id: nodeId, dependsOn: value.dependsOn }
            : { ...baseNode, id: nodeId });
    }
    return result;
}
/** Declare workflow step dependencies. */
export function dependsOn(node, ...dependencies) {
    return {
        ...node,
        dependsOn: [...(node.dependsOn ?? []), ...dependencies],
    };
}
